                 r"\s+([A-Za-z_][A-Za-z0-9_]{4,})", re.M)

def new_names(task):
    removed = lines(task.patch, "-")
    return {n for n in DEF.findall(task.patch)
            if not n.startswith("__") and n not in GENERIC
            and not has(n, removed) and has(n, task.test_patch)}

prompt = "\n".join([task.problem_statement, task.requirements, task.interface])
given = sum(has(n, prompt) for n in new_names(task))

